package com.itsm.domain.incident;

public enum NoteType {
    /** Public comment visible to the reporter. */
    COMMENT,
    /** Internal investigation note, visible to support staff only. */
    WORK_NOTE,
    /** Technician asks the reporter for more information. */
    INFO_REQUEST,
    /** Reporter's answer to an information request. */
    INFO_RESPONSE,
    /** Generated by the system (escalation, duplicate link...). */
    SYSTEM;

    public boolean isInternal() { return this == WORK_NOTE; }
}
